public class ThreadBasics {

    // Approach 1: extend Thread
    static class CounterThread extends Thread {
        CounterThread(String name) { super(name); }

        @Override
        public void run() {
            for (int i = 1; i <= 3; i++) {
                System.out.println(getName() + " -> " + i);
                try { Thread.sleep(100); } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    // Approach 2: implement Runnable
    static class CounterRunnable implements Runnable {
        @Override
        public void run() {
            String name = Thread.currentThread().getName();
            for (int i = 1; i <= 3; i++) {
                System.out.println(name + " -> " + i);
                try { Thread.sleep(100); } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread t1 = new CounterThread("ExtendThread");
        Thread t2 = new Thread(new CounterRunnable(), "RunnableThread");
        // Lambda shorthand — most common in modern code:
        Thread t3 = new Thread(() -> System.out.println("Lambda thread!"), "LambdaThread");

        t1.start();
        t2.start();
        t3.start();

        t1.join(); // main blocks until t1 finishes
        t2.join();
        t3.join();

        System.out.println("Main thread done");
    }
}

