public class DaemonAndInterrupt {

    public static void main(String[] args) throws InterruptedException {
        // Daemon: prints heartbeat, no cleanup on JVM exit
        Thread daemon = new Thread(() -> {
            while (true) {
                System.out.println("[DAEMON] heartbeat");
                try {
                    Thread.sleep(500);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }, "HeartbeatDaemon");
        daemon.setDaemon(true); // MUST be before start()
        daemon.start();

        // Interruptible worker
        Thread worker = new Thread(() -> {
            System.out.println("[WORKER] started");
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    Thread.sleep(200); // interruptible blocking call
                    System.out.println("[WORKER] working...");
                } catch (InterruptedException e) {
                    // sleep() cleared the flag — restore it
                    Thread.currentThread().interrupt();
                    break; // exit the loop
                }
            }
            System.out.println("[WORKER] cleanly stopped");
        }, "Worker");
        worker.start();

        Thread.sleep(1000);
        worker.interrupt(); // signal the worker to stop
        worker.join();      // wait for clean shutdown

        System.out.println("[MAIN] done — daemon will be killed now");
        // JVM exits; daemon thread is killed without running further
    }
}

