public class DoubleCheckedLocking {

    // --- BROKEN DCL (do NOT use) ---
    // Without volatile, the JIT can reorder: instance = new Singleton() to:
    //   1. allocate memory
    //   2. assign reference to 'instance'  <-- another thread sees non-null!
    //   3. call constructor (initialise fields)
    // A second thread can see 'instance != null' but get a partially-constructed object.
    static class BrokenSingleton {
        private static BrokenSingleton instance; // NOT volatile!
        private final int value;
        private BrokenSingleton() { this.value = 42; }
        public static BrokenSingleton getInstance() {
            if (instance == null) {
                synchronized (BrokenSingleton.class) {
                    if (instance == null) {
                        instance = new BrokenSingleton(); // reordering can expose half-built object
                    }
                }
            }
            return instance;
        }
    }

    // --- CORRECT DCL with volatile ---
    static class CorrectSingleton {
        private static volatile CorrectSingleton instance; // volatile ensures ordering!
        private final int value;
        private CorrectSingleton() { this.value = 42; }
        public static CorrectSingleton getInstance() {
            if (instance == null) {                     // 1st check — no lock (fast path)
                synchronized (CorrectSingleton.class) {
                    if (instance == null) {             // 2nd check — under lock
                        instance = new CorrectSingleton();
                    }
                }
            }
            return instance; // after volatile write, safe to read
        }
        public int getValue() { return value; }
    }

    // --- BEST APPROACH: Initialization-on-demand Holder ---
    static class HolderSingleton {
        private HolderSingleton() {}
        private static class Holder {
            static final HolderSingleton INSTANCE = new HolderSingleton();
        }
        public static HolderSingleton getInstance() {
            return Holder.INSTANCE;
        }
    }

    public static void main(String[] args) {
        System.out.println(CorrectSingleton.getInstance().getValue()); // 42
        System.out.println(CorrectSingleton.getInstance() == CorrectSingleton.getInstance()); // true
        System.out.println(HolderSingleton.getInstance() == HolderSingleton.getInstance()); // true
    }
}

