import java.util.concurrent.locks.*;
import java.util.concurrent.TimeUnit;

public class ReentrantLockDemo {
    private final ReentrantLock lock = new ReentrantLock(); // unfair by default (faster)
    private int counter = 0;

    void safeIncrement() {
        lock.lock();
        try {
            counter++; // critical section
        } finally {
            lock.unlock(); // ALWAYS in finally — even if an exception is thrown
        }
    }

    boolean tryIncrement() {
        if (lock.tryLock()) { // non-blocking acquisition
            try {
                counter++;
                return true;
            } finally {
                lock.unlock();
            }
        }
        return false; // lock was held by another thread
    }

    void reentrantDemo() {
        lock.lock(); // acquire once
        try {
            System.out.println("Outer: hold count = " + lock.getHoldCount()); // 1
            lock.lock(); // same thread acquires again — no deadlock!
            try {
                System.out.println("Inner: hold count = " + lock.getHoldCount()); // 2
            } finally {
                lock.unlock(); // release inner
            }
            System.out.println("Back outer: hold count = " + lock.getHoldCount()); // 1
        } finally {
            lock.unlock(); // release outer
        }
    }

    int getCounter() { return counter; }

    public static void main(String[] args) throws InterruptedException {
        ReentrantLockDemo demo = new ReentrantLockDemo();
        Runnable task = () -> { for (int i = 0; i < 10_000; i++) demo.safeIncrement(); };
        Thread t1 = new Thread(task), t2 = new Thread(task);
        t1.start(); t2.start();
        t1.join();  t2.join();
        System.out.println("Counter: " + demo.getCounter()); // 20000

        demo.reentrantDemo();
    }
}

