import java.util.concurrent.locks.*;

public class ReadWriteLockDemo {
    private final ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock(true); // fair
    private final Lock readLock  = rwLock.readLock();
    private final Lock writeLock = rwLock.writeLock();
    private String cachedValue = "initial";

    String getValue() {
        readLock.lock();
        try {
            return cachedValue; // multiple threads can be here at once!
        } finally {
            readLock.unlock();
        }
    }

    void setValue(String value) {
        writeLock.lock(); // blocks until ALL readers and other writers release
        try {
            System.out.println(Thread.currentThread().getName() + " WRITING: " + value);
            cachedValue = value;
            Thread.sleep(100); // simulate slow write
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            writeLock.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ReadWriteLockDemo demo = new ReadWriteLockDemo();

        // 5 readers
        for (int i = 0; i < 5; i++) {
            final int id = i;
            Thread reader = new Thread(() -> {
                for (int j = 0; j < 3; j++) {
                    System.out.println("Reader-" + id + " read: " + demo.getValue());
                    try { Thread.sleep(200); } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }, "Reader-" + i);
            reader.start();
        }

        // 1 writer
        Thread writer = new Thread(() -> {
            String[] values = {"alpha", "beta", "gamma"};
            for (String v : values) {
                demo.setValue(v);
                try { Thread.sleep(300); } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }, "Writer");
        writer.start();
    }
}

