import java.util.concurrent.*;
import java.util.*;

public class ExecutorServiceDemo {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(3);

        // --- Single Callable ---
        Callable<Integer> square = () -> {
            Thread.sleep(200);
            return 7 * 7;
        };
        Future<Integer> future = pool.submit(square);
        System.out.println("Square of 7: " + future.get()); // 49 (blocks up to completion)

        // --- invokeAll: wait for all tasks ---
        List<Callable<String>> tasks = new ArrayList<>();
        for (int i = 1; i <= 5; i++) {
            final int id = i;
            tasks.add(() -> {
                Thread.sleep((long)(Math.random() * 500));
                return "Task-" + id + " done";
            });
        }
        List<Future<String>> futures = pool.invokeAll(tasks); // blocks until ALL finish
        for (Future<String> f : futures) {
            System.out.println(f.get()); // already done — get() returns immediately
        }

        // --- invokeAny: return first successful result ---
        List<Callable<String>> racers = List.of(
            () -> { Thread.sleep(300); return "Slow"; },
            () -> { Thread.sleep(50);  return "Fast"; },
            () -> { Thread.sleep(200); return "Medium"; }
        );
        String winner = pool.invokeAny(racers); // cancels the others
        System.out.println("Winner: " + winner); // Fast

        // --- Shutdown ---
        pool.shutdown(); // stop accepting new tasks
        boolean finished = pool.awaitTermination(5, TimeUnit.SECONDS);
        System.out.println("All done: " + finished);
        // If not finished: pool.shutdownNow() to interrupt running tasks
    }
}

