import java.util.concurrent.atomic.*;

public class AtomicDemo {
    volatile int volatileCounter = 0;
    AtomicInteger atomicCounter = new AtomicInteger(0);

    void unsafeVolatileIncrement() { volatileCounter++; } // still a race!
    void safeAtomicIncrement()     { atomicCounter.incrementAndGet(); }

    // Lock-free max update using CAS loop
    static void updateMax(AtomicInteger maxRef, int newValue) {
        int current;
        do {
            current = maxRef.get();
            if (newValue <= current) return; // nothing to update
        } while (!maxRef.compareAndSet(current, newValue)); // retry if another thread changed it
    }

    // Lock-free stack node
    static class Node<T> {
        final T value;
        final Node<T> next;
        Node(T value, Node<T> next) { this.value = value; this.next = next; }
    }

    static class LockFreeStack<T> {
        private final AtomicReference<Node<T>> top = new AtomicReference<>(null);

        void push(T value) {
            Node<T> newNode;
            do {
                newNode = new Node<>(value, top.get());
            } while (!top.compareAndSet(newNode.next, newNode)); // retry on contention
        }

        T peek() {
            Node<T> node = top.get();
            return node == null ? null : node.value;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        AtomicDemo demo = new AtomicDemo();
        int ITERS = 10_000;

        Runnable unsafeTask = () -> { for (int i = 0; i < ITERS; i++) demo.unsafeVolatileIncrement(); };
        Thread t1 = new Thread(unsafeTask), t2 = new Thread(unsafeTask);
        t1.start(); t2.start(); t1.join(); t2.join();
        System.out.println("Volatile (expected 20000): " + demo.volatileCounter); // likely < 20000

        Runnable safeTask = () -> { for (int i = 0; i < ITERS; i++) demo.safeAtomicIncrement(); };
        Thread t3 = new Thread(safeTask), t4 = new Thread(safeTask);
        t3.start(); t4.start(); t3.join(); t4.join();
        System.out.println("Atomic  (expected 20000): " + demo.atomicCounter.get()); // always 20000

        // CAS max update
        AtomicInteger max = new AtomicInteger(0);
        updateMax(max, 5); updateMax(max, 3); updateMax(max, 9);
        System.out.println("Max: " + max.get()); // 9

        // Lock-free stack
        LockFreeStack<String> stack = new LockFreeStack<>();
        stack.push("first"); stack.push("second");
        System.out.println("Top: " + stack.peek()); // second
    }
}

