import java.util.*;
import java.util.concurrent.*;

public class ConcurrentMapDemo {

    static Map<String, Integer> countWords(String[] words, int threadCount)
            throws InterruptedException {
        ConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();
        List<Thread> threads = new ArrayList<>();
        int chunk = (words.length + threadCount - 1) / threadCount;

        for (int t = 0; t < threadCount; t++) {
            int start = t * chunk;
            int end   = Math.min(start + chunk, words.length);
            threads.add(new Thread(() -> {
                for (int i = start; i < end; i++) {
                    // merge: if key absent, set to 1; else apply Integer::sum atomically
                    map.merge(words[i], 1, Integer::sum);
                }
            }));
        }
        threads.forEach(Thread::start);
        for (Thread th : threads) th.join();
        return map;
    }

    public static void main(String[] args) throws InterruptedException {
        String[] words = {
            "apple","banana","apple","cherry","banana","apple",
            "date","cherry","apple","banana"
        };
        System.out.println(countWords(words, 3)); // {apple=4, banana=3, cherry=2, date=1}

        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        cache.putIfAbsent("config", "default"); // sets it
        cache.putIfAbsent("config", "override"); // ignored — already present
        System.out.println(cache.get("config")); // default

        // WRONG: get() + put() is not atomic — race window between the two!
        // if (map.get(key) == null) { map.put(key, compute(key)); } // BROKEN

        // CORRECT: computeIfAbsent is atomic
        ConcurrentHashMap<String, List<String>> index = new ConcurrentHashMap<>();
        index.computeIfAbsent("java", k -> new ArrayList<>()).add("article1");
        index.computeIfAbsent("java", k -> new ArrayList<>()).add("article2");
        System.out.println(index.get("java")); // [article1, article2]
    }
}

