import java.util.concurrent.*;

public class ProducerConsumer {
    static final String POISON_PILL = "DONE";

    public static void main(String[] args) throws InterruptedException {
        BlockingQueue<String> queue = new LinkedBlockingQueue<>(5); // bounded to 5

        Thread producer = new Thread(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    String task = "Task-" + i;
                    queue.put(task); // BLOCKS if queue has 5 items
                    System.out.println("[P] put:  " + task + "  (size=" + queue.size() + ")");
                    Thread.sleep(100);
                }
                queue.put(POISON_PILL);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "Producer");

        Thread consumer = new Thread(() -> {
            try {
                while (true) {
                    String task = queue.take(); // BLOCKS if queue is empty
                    if (POISON_PILL.equals(task)) break;
                    System.out.println("[C] got:  " + task);
                    Thread.sleep(300); // consumer is slower than producer
                }
                System.out.println("[C] Consumer done");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "Consumer");

        consumer.start();
        producer.start();
        producer.join();
        consumer.join();
    }
}

