import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;

public class CountDownLatchDemo {

    public static void main(String[] args) throws InterruptedException {
        System.out.println("=== Starting Gate ===");
        CountDownLatch gate = new CountDownLatch(1);
        int RUNNERS = 5;

        for (int i = 0; i < RUNNERS; i++) {
            final int id = i;
            new Thread(() -> {
                try {
                    System.out.println("Runner " + id + " at the gate");
                    gate.await(); // all runners wait
                    System.out.println("Runner " + id + " sprinting!");
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }).start();
        }

        Thread.sleep(500); // ensure all runners are waiting
        System.out.println("Ready... Set... GO!");
        gate.countDown(); // releases all runners simultaneously

        Thread.sleep(200);
        System.out.println("\n=== Aggregation ===");

        int N = 4;
        CountDownLatch done = new CountDownLatch(N);
        AtomicLong totalResult = new AtomicLong(0);

        for (int i = 1; i <= N; i++) {
            final int chunk = i * 1000;
            new Thread(() -> {
                long sum = 0;
                for (int j = 0; j < chunk; j++) sum += j;
                totalResult.addAndGet(sum);
                System.out.println(Thread.currentThread().getName() + " computed sum of " + chunk);
                done.countDown(); // signal this worker is done
            }, "Worker-" + i).start();
        }

        done.await(); // main blocks until all 4 workers counted down
        System.out.println("All workers done. Total: " + totalResult.get());
    }
}

