    public static void main(String[] args) throws InterruptedException {
        System.out.println("=== CyclicBarrier ===");
        int THREADS = 3;
        AtomicInteger phaseResult = new AtomicInteger(0);

        CyclicBarrier barrier = new CyclicBarrier(THREADS, () ->
            System.out.println("[BARRIER] All arrived! Phase result: " + phaseResult.get())
        );

        for (int i = 0; i < THREADS; i++) {
            final int id = i;
            new Thread(() -> {
                try {
                    // Phase 1
                    int partial = id * 10;
                    phaseResult.addAndGet(partial);
                    System.out.println("Thread-" + id + " finished phase 1, partial=" + partial);
                    barrier.await(); // wait for all

                    // Phase 2 — all threads start together after barrier
                    System.out.println("Thread-" + id + " starting phase 2");
                    barrier.await(); // wait again for phase 2 completion
                    System.out.println("Thread-" + id + " done");
                } catch (InterruptedException | BrokenBarrierException e) {
                    Thread.currentThread().interrupt();
                }
            }, "Worker-" + i).start();
        }

        Thread.sleep(500);
        System.out.println("\n=== Semaphore (Connection Pool) ===");

        Semaphore pool = new Semaphore(3, true); // 3 permits, fair
        for (int i = 0; i < 5; i++) {
            final int id = i;
            new Thread(() -> {
                try {
                    System.out.println("Client-" + id + " waiting for connection...");
                    pool.acquire(); // blocks if all 3 permits taken
                    System.out.println("Client-" + id + " GOT connection (available: " + pool.availablePermits() + ")");
                    Thread.sleep(500); // use the connection
                    pool.release(); // return permit
                    System.out.println("Client-" + id + " released connection");
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }, "Client-" + i).start();
        }
    }
}

