import java.util.*;
import java.util.concurrent.*;

public class CopyOnWriteDemo {

    public static void main(String[] args) throws InterruptedException {
        // --- ArrayList: ConcurrentModificationException ---
        List<Integer> badList = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5));
        try {
            for (Integer item : badList) {
                if (item == 3) badList.remove(item); // modifies while iterating!
            }
        } catch (ConcurrentModificationException e) {
            System.out.println("ArrayList CME caught: " + e.getClass().getSimpleName());
        }

        // --- CopyOnWriteArrayList: safe iteration ---
        CopyOnWriteArrayList<String> cowList =
            new CopyOnWriteArrayList<>(Arrays.asList("a", "b", "c"));

        Thread writer = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                cowList.add("added-" + i); // creates a new backing array each time
                try { Thread.sleep(50); } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        Thread reader = new Thread(() -> {
            for (String s : cowList) { // iterates a SNAPSHOT — no CME possible
                System.out.println("Read: " + s);
                try { Thread.sleep(30); } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            System.out.println("Reader done — current size: " + cowList.size());
        });

        writer.start(); reader.start();
        writer.join();  reader.join();

        // --- Performance comparison ---
        int N = 100_000;
        List<Integer> al  = new ArrayList<>();
        List<Integer> cow = new CopyOnWriteArrayList<>();

        long t1 = System.currentTimeMillis();
        for (int i = 0; i < N; i++) al.add(i);
        System.out.println("ArrayList add " + N + ": " + (System.currentTimeMillis()-t1) + "ms");

        long t2 = System.currentTimeMillis();
        for (int i = 0; i < N; i++) cow.add(i);
        System.out.println("COWAL add " + N + ": " + (System.currentTimeMillis()-t2) + "ms"); // MUCH slower
    }
}

