import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class ThreadLocalDemo {
    // Each thread gets its own SimpleDateFormat — thread-safe without locks!
    static final ThreadLocal<SimpleDateFormat> sdf =
        ThreadLocal.withInitial(() -> new SimpleDateFormat("yyyy-MM-dd"));

    // Auto-incrementing ID per thread
    static final AtomicInteger nextId = new AtomicInteger(1);
    static final ThreadLocal<Integer> threadId =
        ThreadLocal.withInitial(() -> nextId.getAndIncrement());

    static String formatDate(Date date) {
        return sdf.get().format(date); // sdf.get() is THIS thread's own instance
    }

    public static void main(String[] args) throws InterruptedException {
        Date now = new Date();
        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            threads.add(new Thread(() -> {
                try {
                    System.out.println(Thread.currentThread().getName()
                        + " | id=" + threadId.get()
                        + " | date=" + formatDate(now));
                } finally {
                    // CRITICAL in thread pools: remove before returning thread to pool
                    sdf.remove();
                    threadId.remove();
                }
            }, "T" + i));
        }
        threads.forEach(Thread::start);
        for (Thread t : threads) t.join();

        // Thread pool warning: without remove(), pooled threads carry stale ThreadLocal values
        // across different request handlers — a hard-to-debug bug
    }
}

