import java.util.concurrent.*;
import java.util.*;
import java.util.stream.Collectors;

public class CompletableFutureDemo {

    static CompletableFuture<String> fetchUser(int id) {
        return CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(300); } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            if (id == 99) throw new RuntimeException("User " + id + " not found");
            return "User-" + id;
        });
    }

    static CompletableFuture<String> fetchDetails(String user) {
        return CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(200); } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            return user + "[Premium]";
        });
    }

    public static void main(String[] args) throws Exception {
        // Chain: fetch user THEN fetch their details (sequential async)
        CompletableFuture<String> enriched = fetchUser(1)
            .thenCompose(user -> fetchDetails(user)); // total ~500ms
        System.out.println(enriched.get()); // User-1[Premium]

        // Parallel fetch + combine (total ~300ms, not 600ms)
        CompletableFuture<String> combined = fetchUser(1)
            .thenCombine(fetchUser(2), (u1, u2) -> u1 + " & " + u2);
        System.out.println(combined.get()); // User-1 & User-2

        // Error handling
        CompletableFuture<String> safe = fetchUser(99)
            .exceptionally(ex -> "Unknown User (" + ex.getMessage() + ")");
        System.out.println(safe.get()); // Unknown User (User 99 not found)

        // allOf: wait for multiple and collect
        List<CompletableFuture<String>> futures = List.of(fetchUser(1), fetchUser(2), fetchUser(3));
        CompletableFuture<Void> allDone = CompletableFuture.allOf(
            futures.toArray(new CompletableFuture[0]));
        allDone.join(); // wait for all
        List<String> results = futures.stream()
            .map(CompletableFuture::join)
            .collect(Collectors.toList());
        System.out.println(results); // [User-1, User-2, User-3]
    }
}
